fun longestCommonSubsequence(a: String, b: String): Int {
    val n = a.length
    val m = b.length
    val dp = Array(n + 1) { IntArray(m + 1) }          // dp[i][j] = LCS of a[0 until i] and b[0 until j]
    for (i in 1..n) {
        for (j in 1..m) {
            dp[i][j] = if (a[i - 1] == b[j - 1]) {
                dp[i - 1][j - 1] + 1                    // match: extend the common subsequence
            } else {
                maxOf(dp[i - 1][j], dp[i][j - 1])       // mismatch: drop a character from either side
            }
        }
    }
    return dp[n][m]
}
// Time: O(n * m)   Space: O(n * m)

fun lcsOptimized(a: String, b: String): Int {
    var prev = IntArray(b.length + 1)
    for (i in 1..a.length) {
        val cur = IntArray(b.length + 1)
        for (j in 1..b.length) {
            cur[j] = if (a[i - 1] == b[j - 1]) prev[j - 1] + 1
                     else maxOf(prev[j], cur[j - 1])
        }
        prev = cur
    }
    return prev[b.length]
}
// Time: O(n * m)   Space: O(m)
// You lose the ability to rebuild the string, so use the full table when you need it

fun lcsString(a: String, b: String): String {
    val n = a.length
    val m = b.length
    val dp = Array(n + 1) { IntArray(m + 1) }
    for (i in 1..n) {
        for (j in 1..m) {
            dp[i][j] = if (a[i - 1] == b[j - 1]) dp[i - 1][j - 1] + 1
                       else maxOf(dp[i - 1][j], dp[i][j - 1])
        }
    }

    val sb = StringBuilder()
    var i = n
    var j = m
    while (i > 0 && j > 0) {                           // walk back from the bottom-right corner
        when {
            a[i - 1] == b[j - 1] -> { sb.append(a[i - 1]); i--; j-- }
            dp[i - 1][j] >= dp[i][j - 1] -> i--
            else -> j--
        }
    }
    return sb.reverse().toString()
}
// Time: O(n * m)   Space: O(n * m)

fun longestCommonSubstring(a: String, b: String): Int {
    val dp = Array(a.length + 1) { IntArray(b.length + 1) }
    var best = 0
    for (i in 1..a.length) {
        for (j in 1..b.length) {
            if (a[i - 1] == b[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1
                best = maxOf(best, dp[i][j])
            } else {
                dp[i][j] = 0                           // a substring must be contiguous, so the run ends
            }
        }
    }
    return best
}
// Time: O(n * m)   Space: O(n * m), or O(m) with one row

fun minDistance(a: String, b: String): Int {
    val n = a.length
    val m = b.length
    val dp = Array(n + 1) { IntArray(m + 1) }
    for (i in 0..n) dp[i][0] = i                       // delete all i characters
    for (j in 0..m) dp[0][j] = j                       // insert all j characters
    for (i in 1..n) {
        for (j in 1..m) {
            dp[i][j] = if (a[i - 1] == b[j - 1]) {
                dp[i - 1][j - 1]                        // characters already equal: no cost
            } else {
                1 + minOf(
                    dp[i - 1][j - 1],                   // replace
                    dp[i - 1][j],                       // delete from a
                    dp[i][j - 1]                        // insert into a
                )
            }
        }
    }
    return dp[n][m]
}
// Time: O(n * m)   Space: O(n * m), or O(m) with two rows

fun lisSequence(nums: IntArray): List<Int> {
    if (nums.isEmpty()) return emptyList()
    val n = nums.size
    val dp = IntArray(n) { 1 }                          // longest increasing subsequence ending at i
    val parent = IntArray(n) { -1 }
    var bestIdx = 0
    for (i in 0 until n) {
        for (j in 0 until i) {
            if (nums[j] < nums[i] && dp[j] + 1 > dp[i]) {
                dp[i] = dp[j] + 1
                parent[i] = j                           // remember the predecessor
            }
        }
        if (dp[i] > dp[bestIdx]) bestIdx = i
    }
    val result = ArrayList<Int>()
    var cur = bestIdx
    while (cur != -1) {
        result.add(nums[cur])
        cur = parent[cur]
    }
    result.reverse()
    return result
}
// Time: O(n²)   Space: O(n)

fun lengthOfLIS(nums: IntArray): Int {
    val tails = ArrayList<Int>()                        // tails[k] = smallest tail of an increasing subsequence of length k + 1
    for (x in nums) {
        var lo = 0
        var hi = tails.size
        while (lo < hi) {
            val mid = (lo + hi) / 2
            if (tails[mid] < x) lo = mid + 1 else hi = mid    // first tail that is >= x
        }
        if (lo == tails.size) tails.add(x) else tails[lo] = x
    }
    return tails.size
}
// Time: O(n log n)   Space: O(n)
// For a non-decreasing subsequence use tails[mid] <= x

fun minDeleteDistance(word1: String, word2: String): Int {
    val lcs = longestCommonSubsequence(word1, word2)
    return word1.length + word2.length - 2 * lcs
}
// Time: O(n * m)   Space: O(n * m)

fun minimumDeleteSum(s1: String, s2: String): Int {
    val n = s1.length
    val m = s2.length
    val dp = Array(n + 1) { IntArray(m + 1) }
    for (i in 1..n) dp[i][0] = dp[i - 1][0] + s1[i - 1].code      // delete all of s1's prefix
    for (j in 1..m) dp[0][j] = dp[0][j - 1] + s2[j - 1].code      // delete all of s2's prefix
    for (i in 1..n) {
        for (j in 1..m) {
            dp[i][j] = if (s1[i - 1] == s2[j - 1]) {
                dp[i - 1][j - 1]
            } else {
                minOf(dp[i - 1][j] + s1[i - 1].code, dp[i][j - 1] + s2[j - 1].code)
            }
        }
    }
    return dp[n][m]
}
// Time: O(n * m)   Space: O(n * m)

fun shortestCommonSupersequence(a: String, b: String): String {
    val n = a.length
    val m = b.length
    val dp = Array(n + 1) { IntArray(m + 1) }
    for (i in 1..n) {
        for (j in 1..m) {
            dp[i][j] = if (a[i - 1] == b[j - 1]) dp[i - 1][j - 1] + 1
                       else maxOf(dp[i - 1][j], dp[i][j - 1])
        }
    }

    val sb = StringBuilder()
    var i = n
    var j = m
    while (i > 0 && j > 0) {
        if (a[i - 1] == b[j - 1]) {                     // common character is written once
            sb.append(a[i - 1]); i--; j--
        } else if (dp[i - 1][j] >= dp[i][j - 1]) {
            sb.append(a[i - 1]); i--
        } else {
            sb.append(b[j - 1]); j--
        }
    }
    while (i > 0) { sb.append(a[i - 1]); i-- }          // leftovers
    while (j > 0) { sb.append(b[j - 1]); j-- }
    return sb.reverse().toString()
}
// Time: O(n * m)   Space: O(n * m)

fun longestPalindromeSubseq(s: String): Int {
    val n = s.length
    if (n == 0) return 0
    val dp = Array(n) { IntArray(n) }                   // dp[i][j] = LPS inside s[i..j]
    for (i in n - 1 downTo 0) {
        dp[i][i] = 1
        for (j in i + 1 until n) {
            dp[i][j] = if (s[i] == s[j]) {
                dp[i + 1][j - 1] + 2                    // wrap the inner palindrome with the matching ends
            } else {
                maxOf(dp[i + 1][j], dp[i][j - 1])
            }
        }
    }
    return dp[0][n - 1]
}
// Time: O(n²)   Space: O(n²)
// Minimum insertions to make s a palindrome = n - longestPalindromeSubseq(s)

fun numDistinct(s: String, t: String): Int {
    val n = s.length
    val m = t.length
    val dp = Array(n + 1) { IntArray(m + 1) }           // ways s[0 until i] contains t[0 until j] as a subsequence
    for (i in 0..n) dp[i][0] = 1                        // the empty target has exactly one way
    for (i in 1..n) {
        for (j in 1..m) {
            dp[i][j] = dp[i - 1][j]                     // skip s[i - 1]
            if (s[i - 1] == t[j - 1]) {
                dp[i][j] += dp[i - 1][j - 1]            // or use it to match t[j - 1]
            }
        }
    }
    return dp[n][m]
}
// Time: O(n * m)   Space: O(n * m)
// The answer is guaranteed to fit in a 32-bit Int on the usual platform tests; use Long otherwise

fun isInterleave(s1: String, s2: String, s3: String): Boolean {
    val n = s1.length
    val m = s2.length
    if (n + m != s3.length) return false
    val dp = Array(n + 1) { BooleanArray(m + 1) }       // dp[i][j] = s3[0 until i + j] is an interleaving of s1[0 until i] and s2[0 until j]
    dp[0][0] = true
    for (i in 0..n) {
        for (j in 0..m) {
            if (i > 0 && dp[i - 1][j] && s1[i - 1] == s3[i + j - 1]) dp[i][j] = true
            if (j > 0 && dp[i][j - 1] && s2[j - 1] == s3[i + j - 1]) dp[i][j] = true
        }
    }
    return dp[n][m]
}
// Time: O(n * m)   Space: O(n * m)

fun isMatch(s: String, p: String): Boolean {
    val n = s.length
    val m = p.length
    val dp = Array(n + 1) { BooleanArray(m + 1) }
    dp[0][0] = true
    for (j in 2..m) {
        if (p[j - 1] == '*') dp[0][j] = dp[0][j - 2]    // 'a*' can match the empty string
    }
    for (i in 1..n) {
        for (j in 1..m) {
            if (p[j - 1] == '*') {
                dp[i][j] = dp[i][j - 2]                                    // zero copies of the previous element
                if (p[j - 2] == '.' || p[j - 2] == s[i - 1]) {
                    dp[i][j] = dp[i][j] || dp[i - 1][j]                    // one more copy
                }
            } else if (p[j - 1] == '.' || p[j - 1] == s[i - 1]) {
                dp[i][j] = dp[i - 1][j - 1]
            }
        }
    }
    return dp[n][m]
}
// Time: O(n * m)   Space: O(n * m)

fun isMatchWildcard(s: String, p: String): Boolean {
    val n = s.length
    val m = p.length
    val dp = Array(n + 1) { BooleanArray(m + 1) }
    dp[0][0] = true
    for (j in 1..m) {
        if (p[j - 1] == '*') dp[0][j] = dp[0][j - 1]    // a leading '*' can match nothing
    }
    for (i in 1..n) {
        for (j in 1..m) {
            if (p[j - 1] == '*') {
                dp[i][j] = dp[i][j - 1] || dp[i - 1][j]  // '*' matches empty, or one more character
            } else if (p[j - 1] == '?' || p[j - 1] == s[i - 1]) {
                dp[i][j] = dp[i - 1][j - 1]
            }
        }
    }
    return dp[n][m]
}
// Time: O(n * m)   Space: O(n * m)

fun findNumberOfLIS(nums: IntArray): Int {
    val n = nums.size
    val length = IntArray(n) { 1 }                      // LIS length ending at i
    val count = IntArray(n) { 1 }                       // number of LIS ending at i
    var maxLen = 0
    for (i in 0 until n) {
        for (j in 0 until i) {
            if (nums[j] < nums[i]) {
                if (length[j] + 1 > length[i]) {
                    length[i] = length[j] + 1
                    count[i] = count[j]                 // a strictly better length resets the count
                } else if (length[j] + 1 == length[i]) {
                    count[i] += count[j]                // another way to reach the same length
                }
            }
        }
        maxLen = maxOf(maxLen, length[i])
    }
    var result = 0
    for (i in 0 until n) {
        if (length[i] == maxLen) result += count[i]
    }
    return result
}
// Time: O(n²)   Space: O(n)

fun maxEnvelopes(envelopes: Array<IntArray>): Int {
    // width ascending; for equal widths height DESCENDING so equal widths cannot chain
    envelopes.sortWith(compareBy({ it[0] }, { -it[1] }))
    val tails = ArrayList<Int>()
    for (e in envelopes) {
        val h = e[1]
        var lo = 0
        var hi = tails.size
        while (lo < hi) {
            val mid = (lo + hi) / 2
            if (tails[mid] < h) lo = mid + 1 else hi = mid
        }
        if (lo == tails.size) tails.add(h) else tails[lo] = h
    }
    return tails.size
}
// Time: O(n log n)   Space: O(n)

fun longestStrChain(words: Array<String>): Int {
    words.sortBy { it.length }                          // shorter words first
    val dp = HashMap<String, Int>()                     // longest chain ending at this word
    var best = 1
    for (w in words) {
        var cur = 1
        for (i in w.indices) {
            val predecessor = w.removeRange(i, i + 1)   // delete one character
            cur = maxOf(cur, (dp[predecessor] ?: 0) + 1)
        }
        dp[w] = cur
        best = maxOf(best, cur)
    }
    return best
}
// Time: O(n * L²)   Space: O(n * L)

fun longestSubsequence(arr: IntArray, difference: Int): Int {
    val dp = HashMap<Int, Int>()                        // value -> longest such subsequence ending with it
    var best = 0
    for (x in arr) {
        val len = (dp[x - difference] ?: 0) + 1
        dp[x] = len
        best = maxOf(best, len)
    }
    return best
}
// Time: O(n)   Space: O(n)

fun longestValidParentheses(s: String): Int {
    val dp = IntArray(s.length)                         // dp[i] = longest valid substring ending at i
    var best = 0
    for (i in 1 until s.length) {
        if (s[i] == ')') {
            if (s[i - 1] == '(') {
                dp[i] = (if (i >= 2) dp[i - 2] else 0) + 2          // "...()"
            } else {
                val j = i - dp[i - 1] - 1                           // index before the valid block ending at i - 1
                if (j >= 0 && s[j] == '(') {
                    dp[i] = dp[i - 1] + 2 + (if (j >= 1) dp[j - 1] else 0)
                }
            }
            best = maxOf(best, dp[i])
        }
    }
    return best
}
// Time: O(n)   Space: O(n)

fun findLength(nums1: IntArray, nums2: IntArray): Int {
    val dp = Array(nums1.size + 1) { IntArray(nums2.size + 1) }
    var best = 0
    for (i in 1..nums1.size) {
        for (j in 1..nums2.size) {
            if (nums1[i - 1] == nums2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1          // contiguous run grows
                best = maxOf(best, dp[i][j])
            }                                             // mismatch leaves dp[i][j] = 0
        }
    }
    return best
}
// Time: O(n * m)   Space: O(n * m)
// Same as Longest Common Substring, applied to arrays

fun isSubsequence(s: String, t: String): Boolean {
    var i = 0
    for (c in t) {
        if (i < s.length && s[i] == c) i++
    }
    return i == s.length
}
// Time: O(|t|)   Space: O(1)
// When there are MANY queries for the same t, preprocess positions per letter and binary search
